import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '예산·회계 담당자';
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const DATE_PATTERN = /^\d{4}-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])$/;

function textOf(v: unknown): string {
  return typeof v === 'string' ? v.trim() : '';
}

function idOf(v: unknown, label: string): string | null {
  const t = textOf(v);
  if (t === '') {
    return null;
  }
  if (!/^\d{1,18}$/.test(t)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + '는 숫자여야 합니다.');
  }
  return t;
}

function dateOf(v: unknown, label: string, required: boolean): string | null {
  const t = textOf(v);
  if (t === '') {
    if (required) {
      throw new ApiError(400, 'VALIDATION_FAILED', label + '을(를) 입력해 주세요.');
    }
    return null;
  }
  if (!DATE_PATTERN.test(t)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + '은(는) YYYY-MM-DD 형식이어야 합니다.');
  }
  return t;
}

function pagingOf(q: Record<string, unknown>): { page: number; size: number } {
  const pageText = textOf(q['page']);
  const sizeText = textOf(q['size']);
  if ((pageText !== '' && !/^\d{1,9}$/.test(pageText)) || (sizeText !== '' && !/^\d{1,9}$/.test(sizeText))) {
    throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호와 크기는 숫자여야 합니다.');
  }
  const page = pageText === '' ? 0 : Number(pageText);
  let size = sizeText === '' ? DEFAULT_SIZE : Number(sizeText);
  if (size < 1) {
    size = DEFAULT_SIZE;
  }
  if (size > MAX_SIZE) {
    size = MAX_SIZE;
  }
  return { page, size };
}

// 연령 구간은 개발 담당자가 정한다(결정): 기준일과 전표일자의 일수 차이로 나눈다.
// 반제 기준 잔액 = 전표 라인 금액 - 반제 금액 합계 (가정)
const AGING_CTE =
  'WITH lines AS (' +
  ' SELECT l.account_subject_id AS account_subject_id,' +
  ' CASE' +
  ' WHEN COALESCE(CAST(:baseDate AS date), CURRENT_DATE) - e.entry_date <= 30 THEN \'0~30일\'' +
  ' WHEN COALESCE(CAST(:baseDate AS date), CURRENT_DATE) - e.entry_date <= 60 THEN \'31~60일\'' +
  ' WHEN COALESCE(CAST(:baseDate AS date), CURRENT_DATE) - e.entry_date <= 90 THEN \'61~90일\'' +
  ' ELSE \'91일 이상\' END AS bucket,' +
  ' (l.debit_amount + l.credit_amount) - COALESCE((' +
  ' SELECT SUM(s.settlement_amount) FROM journal_settlement s' +
  ' WHERE s.receivable_line_id = l.journal_entry_line_id OR s.payable_line_id = l.journal_entry_line_id' +
  ' ), 0) AS balance' +
  ' FROM journal_entry_line l' +
  ' JOIN journal_entry e ON e.journal_entry_id = l.journal_entry_id' +
  ' WHERE e.entry_date >= CAST(:startDate AS date)' +
  ' AND e.entry_date <= CAST(:endDate AS date)' +
  ' AND (CAST(:accountSubjectId AS bigint) IS NULL OR l.account_subject_id = CAST(:accountSubjectId AS bigint))' +
  ' AND (CAST(:partnerId AS bigint) IS NULL OR l.partner_id = CAST(:partnerId AS bigint))' +
  '), grouped AS (' +
  ' SELECT account_subject_id, bucket, SUM(balance) AS balance' +
  ' FROM lines GROUP BY account_subject_id, bucket' +
  ') ';

@Controller('api/v1')
export class FnSfr00809Controller {
  @Get('/journal-settlements')
  async listJournalSettlements(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const q = checks.queryOf(req.query) as Record<string, unknown>;
    const startDate = dateOf(q['startDate'], '조회 시작일', true);
    const endDate = dateOf(q['endDate'], '조회 종료일', true);
    const partnerId = idOf(q['partnerId'], '거래처 ID');
    const { page, size } = pagingOf(q);
    return transaction(async (db) => {
      const check = await db.query(
        'SELECT CAST(:startDate AS date) <= CAST(:endDate AS date) AS "valid"',
        { startDate, endDate },
      );
      if (!check[0]['valid']) {
        throw new ApiError(422, 'INVALID_PERIOD', '조회 기간이 올바르지 않습니다.');
      }
      const where =
        ' WHERE settled_at >= CAST(:startDate AS date)' +
        ' AND settled_at < CAST(:endDate AS date) + 1' +
        ' AND (CAST(:partnerId AS bigint) IS NULL OR partner_id = CAST(:partnerId AS bigint))';
      const items = await db.query(
        'SELECT journal_settlement_id AS "journalSettlementId",' +
          ' receivable_line_id AS "receivableLineId",' +
          ' payable_line_id AS "payableLineId",' +
          ' partner_id AS "partnerId",' +
          ' settlement_amount AS "settlementAmount",' +
          ' settled_at AS "settledAt"' +
          ' FROM journal_settlement' +
          where +
          ' ORDER BY settled_at DESC, journal_settlement_id DESC' +
          ' LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)',
        { startDate, endDate, partnerId, size, offset: page * size },
      );
      const totalRows = await db.query(
        'SELECT COUNT(*) AS "total" FROM journal_settlement' + where,
        { startDate, endDate, partnerId },
      );
      return { items, page, size, total: Number(totalRows[0]['total']) };
    });
  }

  @Get('/settlement-aging')
  async listSettlementAging(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const q = checks.queryOf(req.query) as Record<string, unknown>;
    const startDate = dateOf(q['startDate'], '조회 시작일', true);
    const endDate = dateOf(q['endDate'], '조회 종료일', true);
    const baseDate = dateOf(q['baseDate'], '연령분석 기준일', false);
    const accountSubjectId = idOf(q['accountSubjectId'], '계정과목 ID');
    const partnerId = idOf(q['partnerId'], '거래처 ID');
    const { page, size } = pagingOf(q);
    return transaction(async (db) => {
      const check = await db.query(
        'SELECT CAST(:startDate AS date) <= CAST(:endDate AS date) AS "valid"',
        { startDate, endDate },
      );
      if (!check[0]['valid']) {
        throw new ApiError(422, 'INVALID_PERIOD', '조회 기간이 올바르지 않습니다.');
      }
      const filters = { startDate, endDate, baseDate, accountSubjectId, partnerId };
      const items = await db.query(
        AGING_CTE +
          'SELECT account_subject_id AS "accountSubjectId", bucket AS "bucket", CAST(balance AS numeric) AS "balance"' +
          ' FROM grouped' +
          ' ORDER BY account_subject_id, bucket' +
          ' LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)',
        { ...filters, size, offset: page * size },
      );
      const totalRows = await db.query(
        AGING_CTE + 'SELECT COUNT(*) AS "total" FROM grouped',
        filters,
      );
      return { items, page, size, total: Number(totalRows[0]['total']) };
    });
  }
}

