import { useState } from 'react';
import {
  Band,
  DataTable,
  DateInput,
  DateText,
  ErrorText,
  Field,
  Filters,
  LookupSelect,
  Num,
  Pager,
  RefName,
  call,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

type View = 'settlements' | 'aging';

const SIZE = 20;

export default function FnSfr00809Page({ role, notify }: PageProps) {
  const [view, setView] = useState<View>('settlements');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [baseDate, setBaseDate] = useState('');
  const [partnerId, setPartnerId] = useState<number | string>('');
  const [accountSubjectId, setAccountSubjectId] = useState<number | string>('');
  const [applied, setApplied] = useState<Row | null>(null);
  const [page, setPage] = useState(0);

  const path = view === 'settlements' ? '/journal-settlements' : '/settlement-aging';

  const { data, error, loading, reload } = useData<Page | undefined>(async () => {
    if (applied === null) {
      return undefined;
    }
    return call<Page>('GET', path, role, undefined, { ...applied, page, size: SIZE });
  }, [applied, view, page]);

  function search() {
    if (startDate === '' || endDate === '') {
      notify('조회 시작일과 종료일을 입력해 주세요.');
      return;
    }
    if (startDate > endDate) {
      notify('조회 시작일은 종료일보다 늦을 수 없습니다.');
      return;
    }
    const query: Row = { startDate, endDate, partnerId };
    if (view === 'aging') {
      query.baseDate = baseDate;
      query.accountSubjectId = accountSubjectId;
    }
    setPage(0);
    setApplied(query);
  }

  function reset() {
    setStartDate('');
    setEndDate('');
    setBaseDate('');
    setPartnerId('');
    setAccountSubjectId('');
    setPage(0);
    setApplied(null);
  }

  function changeView(next: View) {
    setView(next);
    setApplied(null);
    setPage(0);
  }

  const settlementColumns = [
    { key: 'journalSettlementId', label: '반제·상계 처리 ID' },
    {
      key: 'lines',
      label: '채권 → 채무 분개라인',
      render: (r: Row) => String(r.receivableLineId) + ' → ' + String(r.payableLineId),
    },
    {
      key: 'partnerId',
      label: '거래처',
      render: (r: Row) => <RefName table="partner" role={role} value={r.partnerId} />,
    },
    {
      key: 'settlementAmount',
      label: '반제·상계 금액',
      render: (r: Row) => <Num value={r.settlementAmount} />,
    },
    {
      key: 'settledAt',
      label: '처리일시',
      render: (r: Row) => <DateText value={r.settledAt} time />,
    },
  ];

  const agingColumns = [
    {
      key: 'accountSubjectId',
      label: '계정과목',
      render: (r: Row) => <RefName table="account_subject" role={role} value={r.accountSubjectId} />,
    },
    { key: 'bucket', label: '연령 구간' },
    {
      key: 'balance',
      label: '반제 기준 잔액',
      render: (r: Row) => <Num value={r.balance} />,
    },
  ];

  return (
    <div className="doc">
      <section className="box">
        <h2>전표 반제 관리</h2>
        <div>
          <button className={view === 'settlements' ? '' : 'ghost'} onClick={() => changeView('settlements')}>
            반제처리 현황
          </button>
          <button className={view === 'aging' ? '' : 'ghost'} onClick={() => changeView('aging')}>
            반제 기준 연령분석
          </button>
        </div>
        <Filters onSearch={search} onReset={reset}>
          <Field label="조회 시작일" required>
            <DateInput value={startDate} onChange={setStartDate} />
          </Field>
          <Field label="조회 종료일" required>
            <DateInput value={endDate} onChange={setEndDate} />
          </Field>
          <Field label="거래처 ID">
            <LookupSelect table="partner" role={role} value={partnerId} onChange={setPartnerId} placeholder="전체" />
          </Field>
          {view === 'aging' && (
            <Field label="연령분석 기준일" hint="비우면 오늘 기준입니다.">
              <DateInput value={baseDate} onChange={setBaseDate} />
            </Field>
          )}
          {view === 'aging' && (
            <Field label="계정과목 ID">
              <LookupSelect
                table="account_subject"
                role={role}
                value={accountSubjectId}
                onChange={setAccountSubjectId}
                placeholder="전체"
              />
            </Field>
          )}
        </Filters>
      </section>
      <section className="box">
        {error !== '' && <ErrorText text={error} />}
        {applied === null ? (
          <p>조회 기간을 입력하고 조회 버튼을 눌러 주세요.</p>
        ) : (
          <div>
            <Band total={data ? data.total : 0}>
              <button className="ghost" onClick={reload} disabled={loading}>
                다시 읽기
              </button>
            </Band>
            <DataTable
              columns={view === 'settlements' ? settlementColumns : agingColumns}
              rows={data ? data.items : []}
              empty="조건에 맞는 내역이 없습니다. 조회 기간이나 조건을 바꿔 보세요."
            />
            <Pager page={page} size={SIZE} total={data ? data.total : 0} onPage={setPage} />
          </div>
        )}
      </section>
    </div>
  );
}
